import{_ as t,o,c as a,a5 as r}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Mandatory Engineering & Team Rules (docs/rule/)","description":"","frontmatter":{},"headers":[],"relativePath":"rule/README.md","filePath":"rule/README.md"}'),n={name:"rule/README.md"};function d(c,e,i,s,l,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mandatory-engineering-team-rules-docs-rule" tabindex="-1">Mandatory Engineering &amp; Team Rules (<code>docs/rule/</code>) <a class="header-anchor" href="#mandatory-engineering-team-rules-docs-rule" aria-label="Permalink to &quot;Mandatory Engineering &amp; Team Rules (`docs/rule/`)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./../guides/README.html">Developer Guides →</a> · <a href="./../ba/README.html">BA Baseline &amp; Canonical Roles →</a></p><p>This directory defines the <strong>non-negotiable engineering standards, specification gates, Git conventions, and team SLA charter</strong> enforced across all 7 repositories in the BrandHub polyrepo ecosystem (<code>brandhub-infrastructure</code>, <code>brandhub-api-gateway</code>, <code>brandhub-business-service</code>, <code>brandhub-ai-service</code>, <code>brandhub-publisher-service</code>, <code>brandhub-web</code>, and <code>brandhub-mobile-app</code>).</p><hr><h2 id="_1-core-governance-specifications" tabindex="-1">1. Core Governance Specifications <a class="header-anchor" href="#_1-core-governance-specifications" aria-label="Permalink to &quot;1. Core Governance Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Rule Document</th><th style="text-align:center;">Format</th><th style="text-align:left;">Mandatory Enforcement Scope</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./feature-workflow.html">Feature Workflow (<code>spec → plan → task → test</code>)</a></td><td style="text-align:center;">Markdown</td><td style="text-align:left;">Requires every SRS FR (<code>docs/feature/srs/01..09-*/</code>) and cross-cutting module (<code>docs/feature/modules/*/</code>) to maintain all 4 lifecycle files (<code>spec.md</code>, <code>plan.md</code>, <code>task.md</code>, <code>test.md</code>), strict <strong>6 Canonical Roles</strong> (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), bilingual <code>vi.json</code> + <code>en.json</code> keys, and semantic Light/Dark UI tokens.</td></tr><tr><td style="text-align:left;"><a href="./git-commit-convention.html">Git Commit, Branch &amp; PR Convention</a></td><td style="text-align:center;">Markdown</td><td style="text-align:left;">Enforces lowercase hyphenated branches (<code>&lt;type&gt;/DA-&lt;id&gt;-&lt;kebab-case&gt;</code>), English conventional commit messages (<code>&lt;type&gt;(DA-&lt;id&gt;): &lt;short summary&gt;</code>), Gitleaks + <code>check_sensitive_paths.py</code> pre-commit/CI checks, and <strong>Squash and merge</strong> PRs targeting <code>develop</code>.</td></tr><tr><td style="text-align:left;"><a href="/brandhub-infrastructure/view.html?file=rule/team-rules.html">Team Working Rules (<code>team-rules.html</code>)</a></td><td style="text-align:center;">Interactive HTML</td><td style="text-align:left;">Official 5-member team charter governing sprint ceremonies, deadline SLAs, shared fund accountability, communication response windows, daily async standups, cross-service handoffs, and retrospectives.</td></tr></tbody></table><hr><h2 id="_2-non-negotiable-domain-guardrails-agents-md-sync" tabindex="-1">2. Non-Negotiable Domain Guardrails (<code>AGENTS.md</code> Sync) <a class="header-anchor" href="#_2-non-negotiable-domain-guardrails-agents-md-sync" aria-label="Permalink to &quot;2. Non-Negotiable Domain Guardrails (`AGENTS.md` Sync)&quot;">​</a></h2><ol><li><strong>6 Canonical Role Names Only</strong>: <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code> — never use <code>Agency Owner</code>, <code>Workspace Manager</code>, <code>Account Manager</code>, <code>Content Creator</code>, <code>Brand Client</code>, or <code>System Administrator</code>.</li><li><strong>141 Atomic CRUD FRs (<code>3.2.1</code>–<code>3.10.14</code>)</strong>: Zero <code>&quot;Manage ...&quot;</code> or <code>&quot;... Management&quot;</code> titles; 1-to-1 traceability with <code>UC-001</code>–<code>UC-141</code>.</li><li><strong>Strict Platform &amp; Billing Scope</strong>: Exactly <strong>4 social platforms</strong> (<strong>Facebook, Instagram, TikTok, Threads</strong> — no Zalo OA), <strong>SePay (VietQR)</strong> upgrade-only billing (no downgrade flow, no VNPay/PayOS/Stripe), no Livestream features, and no plagiarism/copyright check FR.</li></ol><hr><h2 id="_3-related-operational-references" tabindex="-1">3. Related Operational References <a class="header-anchor" href="#_3-related-operational-references" aria-label="Permalink to &quot;3. Related Operational References&quot;">​</a></h2><ul><li><strong>8-Step Developer Execution Playbook</strong>: <a href="./../guides/team-workflow-guide.html">guides/team-workflow-guide.md</a></li><li><strong>Feature Specifications Hub (<code>141 SRS FRs</code> + <code>Modules</code>)</strong>: <a href="./../feature/README.html">feature/README.md</a></li><li><strong>System Architecture &amp; Service Boundaries</strong>: <a href="./../architecture/README.html">architecture/README.md</a></li></ul>',12)])])}const h=t(n,[["render",d]]);export{u as __pageData,h as default};
